/** Headless host: no DOM, no pacing; drives a single pass. */
export class NullInteractiveHost {
    live = false;
    pointFromEvent() {
        return [0, 0, 0];
    }
    onPointer(_handlers) {
        return () => { };
    }
    onWheel(_handler) {
        return () => { };
    }
    addButton(_label, _onClick, _icon) {
        return () => { };
    }
    setButtonsEnabled(_enabled) { }
    onKey(_handlers) {
        return () => { };
    }
    beginTextEdit(_mobject, _camera, _options) { }
    endTextEdit() { }
    nextFrame() {
        return Promise.resolve();
    }
}
